import type { ChartVisual, SpatialVisual, VisualAsset } from '../../../shared/types.js';
import { academicNumericModels, academicProcessModels } from './writing-academic-references.js';

export interface WritingAcademicPack {
  key: string; title: string; topic: string; family: string; prompt: string;
  visuals: VisualAsset[]; model: string; keyPoints: string[];
}
const summarise = 'Summarise the information by selecting and reporting the main features, and make comparisons where relevant.';
const chart = (key: string, type: ChartVisual['type'], title: string, unit: string, series: string[], data: [string, ...number[]][]): ChartVisual => ({ id: `fresh-x3-w-${key}`, type, title, unit, series, rows: data.map(([label, ...values]) => ({ label, values })) });
function numeric(key: string, title: string, topic: string, family: string, prompt: string, visuals: ChartVisual[], overview: string, comparison: string): WritingAcademicPack {
  const model = academicNumericModels[key];
  if (!model) throw new Error(`Missing individually authored Academic report: ${key}`);
  return { key, title, topic, family, prompt: `${prompt} ${summarise}`, visuals, model, keyPoints: [overview, comparison, 'Use the units in the visual. Report only displayed measurements; do not invent reasons or unreported totals.'] };
}

const lines: WritingAcademicPack[] = [
  numeric('food-parcels', 'Food-bank deliveries through the year', 'Social support', 'line', 'The line graph shows the number of food parcels delivered each month by three community organisations during 2025.', [chart('food-parcels', 'line', 'Monthly food-parcel deliveries, 2025', 'parcels', ['Neighbourhood Trust', 'Community Pantry', 'Student Volunteers'], [['January', 640, 480, 150], ['March', 620, 515, 185], ['May', 580, 570, 210], ['July', 605, 635, 190], ['September', 690, 710, 265], ['November', 760, 745, 320]])], 'Neighbourhood Trust began and ended with the most deliveries, although Community Pantry overtook it in the middle months. Student Volunteers remained much smaller but more than doubled its monthly total.', 'By November the two larger organisations were only 15 parcels apart, compared with a gap of 160 in January. The graph counts delivered parcels, rather than different households receiving assistance.'),
  numeric('vet-wait', 'Waiting times for rural veterinary visits', 'Rural services', 'line', 'The graph compares average waiting times for non-emergency farm visits by three veterinary services between 2011 and 2025.', [chart('vet-wait', 'line', 'Waiting time for a booked farm visit', 'days', ['North district', 'East district', 'West district'], [['2011', 12, 9, 6], ['2014', 11, 10, 7], ['2017', 8, 11, 8], ['2020', 7, 9, 9], ['2023', 5, 8, 7], ['2025', 4, 6, 5]])], 'waiting times were lower in all three districts by the end. North district had the longest initial wait but the shortest final one, while the other two services experienced temporary increases before improving.', 'The spread between districts narrowed from six days in 2011 to two in 2025. Non-emergency appointments are the only visits included, so these figures do not describe response times to urgent cases.'),
  numeric('multilingual-tours', 'Languages chosen for museum tours', 'Museums and tourism', 'line', 'The graph shows annual bookings for guided museum tours in three languages from 2010 to 2025.', [chart('multilingual-tours', 'line', 'Annual guided-tour bookings', 'thousand bookings', ['English', 'Spanish', 'Mandarin'], [['2010', 48, 17, 5], ['2013', 52, 20, 8], ['2016', 57, 24, 14], ['2019', 54, 29, 22], ['2022', 63, 31, 33], ['2025', 68, 35, 42]])], 'English tours remained the most booked, despite a small fall in 2019. Mandarin bookings grew from a low base and overtook Spanish, which increased more gradually.', 'English exceeded Mandarin by 43 thousand bookings initially, but this difference was 26 thousand at the end. Bookings indicate demand for tours, not the total number of visitors entering the museum.'),
  numeric('rechargeable-tools', 'Repair workshop equipment use', 'Repair and reuse', 'line', 'The line graph shows monthly reservations for three types of equipment at a public repair workshop over six selected months in 2024.', [chart('rechargeable-tools', 'line', 'Monthly equipment reservations', 'reservations', ['Sewing machines', 'Woodworking benches', 'Electronics stations'], [['February', 85, 112, 42], ['April', 104, 126, 58], ['June', 128, 119, 79], ['August', 117, 110, 101], ['October', 146, 134, 120], ['December', 158, 140, 137]])], 'all three equipment categories ended above their opening levels. Sewing machines became the most frequently reserved, whereas electronics stations remained slightly below woodworking benches despite their much faster expansion.', 'The final difference between electronics stations and woodworking benches was only three reservations. Sewing-machine bookings dipped in August but subsequently recovered, so their increase was not continuous.'),
  numeric('heat-nights', 'Summer night temperatures in different districts', 'Urban climate', 'line', 'The graph shows the mean summer night temperature in three areas of a city at five-year intervals between 2000 and 2025.', [chart('heat-nights', 'line', 'Mean summer night temperature', 'degrees Celsius', ['Central commercial area', 'Residential suburb', 'Wooded fringe'], [['2000', 21.4, 19.1, 17.8], ['2005', 21.9, 19.4, 18.1], ['2010', 22.8, 20.2, 18.7], ['2015', 22.5, 20.1, 18.5], ['2020', 23.7, 21.3, 19.6], ['2025', 24.1, 21.8, 20.2]])], 'the commercial centre was consistently warmest and the wooded fringe coolest. All areas became warmer overall, with a slight interruption in 2015.', 'The centre-to-fringe difference increased from 3.6 degrees to 3.9 degrees. The observations describe average summer nights and cannot be interpreted as annual temperatures or maximum daytime readings.'),
  numeric('renewable-apprentices', 'Applications for energy apprenticeships', 'Vocational education', 'line', 'The graph shows applications to three energy-sector apprenticeship programmes between 2014 and 2025.', [chart('renewable-apprentices', 'line', 'Annual apprenticeship applications', 'applications', ['Solar installation', 'Wind maintenance', 'Building insulation'], [['2014', 280, 190, 410], ['2017', 425, 240, 395], ['2020', 610, 385, 430], ['2023', 745, 590, 475], ['2025', 890, 680, 510]])], 'solar installation experienced the greatest growth and became the leading programme. Wind maintenance also expanded substantially, while building insulation rose modestly after an early decline.', 'In 2014 insulation attracted 130 more applicants than solar, but solar had a lead of 380 by 2025. These are applications, so the graph provides no information about places offered or successful completion.'),
  numeric('archive-downloads', 'Use of an online historical archive', 'Digital heritage', 'line', 'The line graph shows annual downloads of three collections from a historical archive between 2012 and 2024.', [chart('archive-downloads', 'line', 'Downloads from three archive collections', 'thousand downloads', ['Photographs', 'Oral histories', 'Digitised newspapers'], [['2012', 64, 12, 83], ['2015', 79, 24, 101], ['2018', 108, 39, 126], ['2021', 142, 76, 151], ['2024', 155, 118, 144]])], 'photographs and oral histories increased throughout, while newspaper downloads fell in the final interval. Newspapers led until photographs overtook them, and oral histories remained the smallest collection by downloads.', 'The photographic collection gained 91 thousand annual downloads, compared with 106 thousand for oral histories. The closing gap between these two collections was 37 thousand, far smaller than their relative difference at the start.'),
  numeric('reservoir-levels', 'Reservoir storage during a dry season', 'Water resources', 'line', 'The graph shows the percentage of usable storage filled in three reservoirs at six monthly observations in 2025.', [chart('reservoir-levels', 'line', 'Usable reservoir storage filled', '% of usable capacity', ['Upland reservoir', 'Riverbank reservoir', 'Southern reservoir'], [['May', 88, 72, 65], ['June', 79, 69, 59], ['July', 65, 60, 52], ['August', 49, 54, 44], ['September', 45, 51, 48], ['October', 57, 63, 56]])], 'all reservoirs finished less full than in May, after falling for much of the season and then recovering. Upland began with the highest percentage but Riverbank had the most storage filled at the final observation.', 'The initial difference between Upland and Southern was 23 percentage points, falling to one point by October. The capacities in litres are not supplied, so a larger percentage cannot be assumed to represent more water.'),
  numeric('adult-orchestras', 'Membership of adult music groups', 'Culture and leisure', 'line', 'The line graph gives membership totals for three adult music groups from 2007 to 2025.', [chart('adult-orchestras', 'line', 'Adult music-group membership', 'members', ['Community choir', 'Amateur orchestra', 'Folk ensemble'], [['2007', 145, 98, 32], ['2010', 156, 104, 41], ['2013', 172, 115, 53], ['2016', 169, 128, 70], ['2019', 185, 121, 86], ['2022', 204, 137, 94], ['2025', 218, 146, 103]])], 'the choir remained the largest group and the folk ensemble the smallest. Membership increased overall in each case, although the choir and orchestra both had brief reversals.', 'The folk ensemble added 71 members and more than tripled its initial membership. The orchestra gained 48, while the choir gained 73, the largest absolute increase among the three groups.'),
  numeric('telemedicine', 'Remote specialist consultations', 'Healthcare access', 'line', 'The graph compares the percentage of specialist consultations conducted remotely in three medical fields from 2015 to 2025.', [chart('telemedicine', 'line', 'Specialist consultations conducted remotely', '% of consultations', ['Dermatology', 'Mental health', 'Physiotherapy'], [['2015', 7, 11, 3], ['2017', 10, 18, 5], ['2019', 16, 27, 9], ['2021', 38, 54, 24], ['2023', 32, 49, 20], ['2025', 35, 58, 22]])], 'mental health consistently had the highest remote-consultation share, and physiotherapy the lowest. All three fields rose substantially, but their paths included a decline after 2021.', 'Mental health ended four percentage points above its 2021 level, while dermatology and physiotherapy were still below their peaks. The graph does not show the total number of consultations or clinical outcomes.'),
  numeric('weekday-swimming', 'Public swimming at different times', 'Sport and recreation', 'line', 'The graph shows average weekday admissions to a municipal pool in three time periods from 2016 to 2025.', [chart('weekday-swimming', 'line', 'Pool admissions on an average weekday', 'admissions', ['Before 9 a.m.', '9 a.m.–5 p.m.', 'After 5 p.m.'], [['2016', 95, 240, 180], ['2018', 118, 252, 204], ['2020', 126, 235, 228], ['2022', 151, 260, 271], ['2024', 176, 278, 286], ['2025', 183, 289, 281]])], 'morning admissions rose steadily from the lowest starting point. Evening use overtook daytime use temporarily, but the daytime period regained the lead at the end.', 'Daytime admissions increased by 49 over the whole period, compared with 101 for evenings and 88 before 9 a.m. Admissions are visits; a swimmer attending repeatedly may therefore be counted more than once.'),
];

const bars: WritingAcademicPack[] = [
  numeric('roof-heat', 'Surface temperatures of roofing materials', 'Building design', 'bar', 'The bar chart compares the average surface temperatures of four roof types at noon and 4 p.m. on the same summer day.', [chart('roof-heat', 'bar', 'Roof surface temperature', 'degrees Celsius', ['Noon', '4 p.m.'], [['Dark tiles', 61, 54], ['Light tiles', 46, 42], ['Vegetated roof', 34, 32], ['Reflective coating', 38, 35]])], 'dark tiles were hottest at both times and the vegetated roof coolest. Every surface had a lower temperature at 4 p.m., with the largest fall for dark tiles.', 'The temperature difference between dark tiles and the vegetated roof was 27 degrees at noon and 22 degrees later. These readings concern roof surfaces, rather than temperatures inside the buildings.'),
  numeric('preventive-dental', 'Attendance at preventive dental checks', 'Preventive healthcare', 'bar', 'The bar chart shows the percentage of adults in four age groups attending a preventive dental appointment in 2013 and 2025.', [chart('preventive-dental', 'bar', 'Adults attending a preventive dental appointment', '% of adults in each age group', ['2013', '2025'], [['18–29', 42, 57], ['30–44', 61, 69], ['45–59', 55, 66], ['60 and over', 38, 54]])], 'attendance increased in every age group. Adults aged 30–44 remained most likely to attend, while those aged 60 and over stayed lowest, despite having the largest gain.', 'The oldest group rose by sixteen percentage points, compared with eight points for people aged 30–44. The gap between these groups narrowed from 23 to 15 points over the period.'),
  numeric('public-hearings', 'Participation in local planning hearings', 'Civic participation', 'bar', 'The chart compares the percentages of residents in four housing types who attended a local planning hearing or submitted written comments during 2025. A resident could participate through both methods.', [chart('public-hearings', 'bar', 'Residents participating in planning consultation', '% of residents in each housing type', ['Attended a hearing', 'Submitted written comments'], [['Owner-occupied houses', 19, 31], ['Rented houses', 13, 24], ['Owner-occupied flats', 22, 38], ['Rented flats', 11, 27]])], 'written participation exceeded hearing attendance in every housing category. Owners of flats led on both measures, whereas renters of flats had the lowest hearing-attendance rate.', 'The two participation measures are not mutually exclusive: a resident could both attend and write. Their percentages should not be added to estimate the overall proportion taking part in the consultation.'),
  numeric('composting', 'Household composting by garden size', 'Household waste', 'bar', 'The chart shows the percentages of households composting food scraps and garden waste in 2024, classified by garden size.', [chart('composting', 'bar', 'Households composting two types of waste', '% of households in each category', ['Food scraps', 'Garden waste'], [['No garden', 18, 4], ['Small garden', 39, 46], ['Medium garden', 51, 68], ['Large garden', 58, 82]])], 'both kinds of composting were more common among households with larger gardens. Food-scrap composting was more frequent than garden-waste composting only in homes without a garden.', 'For large gardens the difference between the two rates was 24 percentage points. The categories refer to household participation, rather than the weight of material composted or the amount each household produced.'),
  numeric('flood-awareness', 'Knowledge of coastal flood warnings', 'Disaster preparedness', 'bar', 'The chart shows the percentages of respondents in four age groups who could correctly identify a flood-warning symbol and name their nearest evacuation point in a 2025 survey.', [chart('flood-awareness', 'bar', 'Correct answers to two preparedness questions', '% of respondents in each age group', ['Warning symbol', 'Evacuation point'], [['16–24', 64, 37], ['25–39', 79, 55], ['40–59', 85, 68], ['60 and over', 72, 61]])], 'warning symbols were recognised more often than evacuation points across all ages. Respondents aged 40–59 performed best on both questions, while the youngest group had the lowest percentages.', 'The gap between the two measures was greatest among the youngest respondents, at 27 percentage points, and smallest among the oldest, at eleven. Correct survey answers do not directly measure behaviour during an actual flood.'),
  numeric('research-methods', 'Methods selected for university dissertations', 'Higher education', 'bar', 'The chart compares the percentages of dissertations in four academic departments that used interviews or numerical surveys in 2024. A dissertation could use both methods.', [chart('research-methods', 'bar', 'Dissertations using selected research methods', '% of dissertations in each department', ['Interviews', 'Numerical surveys'], [['Education', 62, 45], ['Business', 34, 71], ['Sociology', 68, 56], ['Environmental studies', 39, 63]])], 'interviews were more common in education and sociology, whereas numerical surveys led in business and environmental studies. Sociology had the highest interview share, and business the highest survey share.', 'Some dissertations used both methods, so the two percentages for a department need not sum to 100%. Business had the widest difference between methods, with surveys ahead of interviews by 37 percentage points.'),
  numeric('childcare-hours', 'Time spent on unpaid childcare', 'Family and work', 'bar', 'The bar chart compares average weekly unpaid childcare hours among adults in four employment categories in one country in 2025.', [chart('childcare-hours', 'bar', 'Weekly unpaid childcare among surveyed parents', 'hours per week', ['Mothers', 'Fathers'], [['Full-time employed', 24, 16], ['Part-time employed', 35, 23], ['Self-employed', 29, 21], ['Not in paid work', 48, 39]])], 'mothers reported more childcare than fathers in every employment category. Parents outside paid employment spent the most time on it, and full-time employees the least.', 'The mother–father gap ranged from eight hours among full-time employees and the self-employed to twelve among part-time employees. These averages apply to surveyed parents, rather than every adult in the population.'),
  numeric('allergen-checks', 'Checking allergen information when shopping', 'Food safety', 'bar', 'The chart shows how frequently shoppers in four age groups checked allergen labels when buying a new food product in a 2025 survey. Only the always and sometimes response categories are shown.', [chart('allergen-checks', 'bar', 'Checking labels on an unfamiliar food product', '% of surveyed shoppers', ['Always', 'Sometimes'], [['18–29', 27, 49], ['30–44', 44, 41], ['45–59', 51, 33], ['60 and over', 46, 29]])], 'always checking was more common than sometimes checking among shoppers aged 30 and above. The youngest group displayed the opposite pattern, while the 45–59 group had the highest always-checking share.', 'The chart omits the remaining responses, so it cannot be assumed that these two frequencies account for all shoppers. Among the youngest, sometimes checking exceeded always checking by 22 percentage points.'),
  numeric('night-trains', 'Punctuality of overnight train services', 'Rail transport', 'bar', 'The bar chart shows the percentages of overnight trains arriving within ten minutes of schedule on four routes in 2014 and 2025.', [chart('night-trains', 'bar', 'Overnight trains arriving within ten minutes of schedule', '% of trains on each route', ['2014', '2025'], [['Coastal route', 76, 89], ['Mountain route', 68, 81], ['Capital route', 91, 87], ['Border route', 72, 84]])], 'three routes improved, with the coastal service becoming the most punctual. The capital route was the only one to decline and lost its initial leading position.', 'The mountain and coastal routes each improved by thirteen percentage points, while the border route gained twelve. Being within ten minutes includes small delays, so these are not strictly on-time arrival percentages.'),
  numeric('volunteer-shifts', 'Volunteer time in sports clubs', 'Community sport', 'bar', 'The chart compares average monthly volunteer hours per active volunteer in four types of amateur sports club in 2025.', [chart('volunteer-shifts', 'bar', 'Monthly hours per active volunteer', 'hours per month', ['Administration', 'Coaching'], [['Football', 8, 17], ['Swimming', 6, 21], ['Athletics', 11, 15], ['Tennis', 9, 12]])], 'coaching took more volunteer time than administration in every club type. Swimming had the highest coaching figure but the lowest administrative one, while tennis recorded the least coaching time.', 'The gap between coaching and administration ranged from fifteen hours for swimming to three for tennis. These are averages per volunteer, and the chart supplies no totals for the number of volunteers in each sport.'),
  numeric('printer-lifespan', 'Service life of office equipment', 'Manufacturing and consumption', 'bar', 'The chart compares average years of service for new and professionally remanufactured equipment in four office-equipment categories.', [chart('printer-lifespan', 'bar', 'Average equipment service life', 'years', ['New', 'Remanufactured'], [['Desktop printers', 6.4, 5.8], ['Large copiers', 8.1, 7.5], ['Document scanners', 7.2, 6.9], ['Label printers', 5.7, 5.1]])], 'new equipment lasted slightly longer in every category. Large copiers had the longest service life under both conditions, and label printers the shortest.', 'The difference between new and remanufactured units was only 0.3 years for scanners, compared with 0.6 years in each of the other categories. The chart does not state purchase prices or maintenance costs.'),
];

const pies: WritingAcademicPack[] = [
  numeric('textile-disposal', 'What households do with unwanted clothing', 'Recycling and consumption', 'pie', 'The pie charts show how unwanted household clothing, measured by weight, was disposed of in a city in 2009 and 2025.', [chart('textile-disposal-before', 'pie', 'Unwanted clothing, 2009', '% of total weight', ['Share'], [['General rubbish', 58], ['Charity donation', 24], ['Textile recycling', 9], ['Resale', 5], ['Other', 4]]), chart('textile-disposal-after', 'pie', 'Unwanted clothing, 2025', '% of total weight', ['Share'], [['General rubbish', 31], ['Charity donation', 29], ['Textile recycling', 22], ['Resale', 14], ['Other', 4]])], 'general rubbish remained the largest category but its share fell sharply. Donation, recycling and resale all gained share, with textile recycling showing the largest increase among these alternatives.', 'Donation and resale together increased from 29% to 43%. Total clothing weight is not given, so the falling rubbish share does not establish that fewer tonnes were thrown away.'),
  numeric('research-funding', 'Sources of a research institute budget', 'Science funding', 'pie', 'The charts show the sources of a research institute’s funding in 2010 and 2025. Its total income was 12 million currency units and 18 million respectively.', [chart('research-funding-before', 'pie', 'Research institute income, 2010: 12 million', '% of total income', ['Share'], [['Government grants', 52], ['Industry contracts', 21], ['Charitable grants', 14], ['International grants', 8], ['Other income', 5]]), chart('research-funding-after', 'pie', 'Research institute income, 2025: 18 million', '% of total income', ['Share'], [['Government grants', 39], ['Industry contracts', 28], ['Charitable grants', 12], ['International grants', 16], ['Other income', 5]])], 'government grants remained the largest source but lost share, while industry contracts and international grants became more prominent. The institute’s total income increased by half.', 'Despite a fall in share, government funding rose from 6.24 to 7.02 million currency units. International grants increased from 0.96 to 2.88 million, tripling in amount rather than merely doubling.'),
  numeric('reserve-habitats', 'Land cover inside a wildlife reserve', 'Conservation', 'pie', 'The pie charts show the distribution of land cover in a wildlife reserve in 1990 and 2025. The reserve’s total area remained 2,000 hectares.', [chart('reserve-habitats-before', 'pie', 'Reserve land cover, 1990', '% of reserve area', ['Share'], [['Woodland', 44], ['Grassland', 28], ['Wetland', 12], ['Farmland', 11], ['Other', 5]]), chart('reserve-habitats-after', 'pie', 'Reserve land cover, 2025', '% of reserve area', ['Share'], [['Woodland', 47], ['Grassland', 21], ['Wetland', 22], ['Farmland', 4], ['Other', 6]])], 'woodland continued to occupy the largest area and grew slightly in share. Wetland almost doubled its share, while farmland and grassland declined.', 'Because the reserve remained the same size, wetland increased from 240 to 440 hectares. Farmland decreased from 220 to 80 hectares, a reduction of 140 hectares over the period.'),
  numeric('festival-income', 'Revenue of a summer arts festival', 'Culture and finance', 'pie', 'The charts show the sources of income for an arts festival in 2011 and 2025. Total income was 800,000 and 1,200,000 currency units respectively.', [chart('festival-income-before', 'pie', 'Festival income, 2011: 800,000', '% of income', ['Share'], [['Ticket sales', 61], ['Public subsidy', 18], ['Corporate sponsorship', 12], ['Food stalls', 6], ['Merchandise', 3]]), chart('festival-income-after', 'pie', 'Festival income, 2025: 1,200,000', '% of income', ['Share'], [['Ticket sales', 48], ['Public subsidy', 14], ['Corporate sponsorship', 23], ['Food stalls', 10], ['Merchandise', 5]])], 'ticket sales remained the main source but represented less than half of income in 2025. Sponsorship became the second-largest source, overtaking the public subsidy.', 'Ticket income grew from 488,000 to 576,000 currency units despite its smaller share. Public subsidy also rose in amount, from 144,000 to 168,000, because the overall income total increased.'),
  numeric('freshwater-use', 'Allocation of freshwater withdrawals', 'Natural resources', 'pie', 'The charts show the shares of freshwater withdrawn for five purposes in a region in 2000 and 2025. They describe withdrawals rather than final consumption.', [chart('freshwater-use-before', 'pie', 'Freshwater withdrawals, 2000', '% of withdrawn water', ['Share'], [['Irrigation', 54], ['Industry', 23], ['Households', 15], ['Power generation', 6], ['Other', 2]]), chart('freshwater-use-after', 'pie', 'Freshwater withdrawals, 2025', '% of withdrawn water', ['Share'], [['Irrigation', 43], ['Industry', 19], ['Households', 26], ['Power generation', 9], ['Other', 3]])], 'irrigation remained the largest user by share, although its proportion declined. Households overtook industry as the second-largest category, while power generation and other uses gained smaller shares.', 'Irrigation and industry together accounted for 77% initially but only 62% in 2025. No total withdrawal volumes are provided, so the charts cannot establish changes in actual litres taken from freshwater sources.'),
  numeric('housing-tenure', 'Housing tenure among newly formed households', 'Housing', 'pie', 'The pie charts compare housing tenure among households formed within the previous year in a country in 2005 and 2025.', [chart('housing-tenure-before', 'pie', 'New households, 2005', '% of newly formed households', ['Share'], [['Owner with mortgage', 42], ['Owner without mortgage', 11], ['Private rental', 29], ['Public rental', 14], ['Other', 4]]), chart('housing-tenure-after', 'pie', 'New households, 2025', '% of newly formed households', ['Share'], [['Owner with mortgage', 31], ['Owner without mortgage', 8], ['Private rental', 43], ['Public rental', 12], ['Other', 6]])], 'private rental replaced ownership with a mortgage as the most common tenure. The combined ownership share declined, while private renting and other arrangements became more frequent.', 'Owner occupation, with and without a mortgage, fell from 53% to 39%. These distributions concern recently established households, not the housing tenure of all households in the country.'),
  numeric('hospital-energy', 'Energy sources used by a regional hospital', 'Energy and healthcare', 'pie', 'The charts show the sources of energy consumed by a regional hospital in 2008 and 2025, measured in energy-equivalent units.', [chart('hospital-energy-before', 'pie', 'Hospital energy sources, 2008', '% of energy consumed', ['Share'], [['Grid electricity', 47], ['Natural gas', 38], ['Oil', 11], ['Solar', 2], ['Other', 2]]), chart('hospital-energy-after', 'pie', 'Hospital energy sources, 2025', '% of energy consumed', ['Share'], [['Grid electricity', 42], ['Natural gas', 29], ['Oil', 3], ['Solar', 21], ['Other', 5]])], 'grid electricity remained the largest source, while solar’s share expanded substantially. Natural gas and especially oil accounted for smaller portions of the energy mix.', 'The combined gas-and-oil share fell from 49% to 32%, whereas solar and other sources together rose from 4% to 26%. The charts do not supply total consumption or emissions, so neither change can be calculated.'),
  numeric('radio-airtime', 'Programme allocation on a radio station', 'Broadcast media', 'pie', 'The charts show how a radio station divided its weekly broadcasting hours among programme types in 1995 and 2025.', [chart('radio-airtime-before', 'pie', 'Weekly broadcasting hours, 1995', '% of airtime', ['Share'], [['Music', 48], ['News', 22], ['Talk shows', 12], ['Sport', 10], ['Documentaries', 8]]), chart('radio-airtime-after', 'pie', 'Weekly broadcasting hours, 2025', '% of airtime', ['Share'], [['Music', 34], ['News', 19], ['Talk shows', 27], ['Sport', 8], ['Documentaries', 12]])], 'music remained the largest programme category but lost a substantial share of airtime. Talk shows more than doubled their share and moved ahead of news into second place.', 'Music and news together accounted for 70% of broadcasts in 1995 and 53% in 2025. The station’s total weekly broadcast hours are unspecified, so the figures cannot be converted reliably into hours.'),
  numeric('fruit-sales', 'Types of fruit sold by a growers cooperative', 'Food distribution', 'pie', 'The pie charts show the distribution by weight of fruit sold by a growers cooperative in 2010 and 2025. Total sales were 5,000 and 8,000 tonnes respectively.', [chart('fruit-sales-before', 'pie', 'Fruit sales, 2010: 5,000 tonnes', '% of fruit weight sold', ['Share'], [['Apples', 41], ['Pears', 26], ['Peaches', 17], ['Plums', 10], ['Berries', 6]]), chart('fruit-sales-after', 'pie', 'Fruit sales, 2025: 8,000 tonnes', '% of fruit weight sold', ['Share'], [['Apples', 33], ['Pears', 19], ['Peaches', 16], ['Plums', 12], ['Berries', 20]])], 'apples retained the largest share, while berries moved from the smallest category into second place. Apples, pears and peaches lost share, although total fruit sales increased.', 'Berry sales rose from 300 to 1,600 tonnes. Apple sales also increased, from 2,050 to 2,640 tonnes, illustrating why a falling share need not mean a fall in the quantity sold.'),
  numeric('coding-lab', 'Activities at a public digital learning centre', 'Adult learning', 'pie', 'The charts show how booked computer hours at a public digital learning centre were distributed among five activities in 2014 and 2025.', [chart('coding-lab-before', 'pie', 'Booked computer hours, 2014', '% of booked hours', ['Share'], [['Basic computer skills', 45], ['Job applications', 24], ['Coding', 12], ['Digital design', 10], ['Other', 9]]), chart('coding-lab-after', 'pie', 'Booked computer hours, 2025', '% of booked hours', ['Share'], [['Basic computer skills', 26], ['Job applications', 21], ['Coding', 25], ['Digital design', 19], ['Other', 9]])], 'basic skills retained the largest share but were almost matched by coding in 2025. Coding and design became much more prominent, while job applications declined slightly in share.', 'Coding and design together increased from 22% to 44% of booked hours. These shares refer to computer use, not the number of learners, and the same learner could book several different activities.'),
  numeric('car-service', 'Sources of revenue at a vehicle workshop', 'Business services', 'pie', 'The pie charts show the shares of revenue earned by a vehicle workshop from five services in 2006 and 2025.', [chart('car-service-before', 'pie', 'Workshop revenue, 2006', '% of revenue', ['Share'], [['Routine servicing', 46], ['Engine repairs', 27], ['Tyres', 14], ['Bodywork', 9], ['Electrical work', 4]]), chart('car-service-after', 'pie', 'Workshop revenue, 2025', '% of revenue', ['Share'], [['Routine servicing', 35], ['Engine repairs', 18], ['Tyres', 17], ['Bodywork', 10], ['Electrical work', 20]])], 'routine servicing remained the largest revenue source, but engine repairs lost its second-place ranking to electrical work. The latter increased fivefold as a proportion of total revenue.', 'Routine servicing and engine repairs together fell from 73% to 53%. Overall revenue is not reported, so these changing shares do not establish whether the workshop earned more or less money from any individual service.'),
];

