/** Each family contains eight lesson stimuli; the remaining stimuli are reserved
 * for independent two-task mocks rather than repeated as standalone lessons. */
export const expandedAcademicLessons: WritingAcademicPack[] = [lines, bars, pies, tables, maps, processes, mixed].flatMap(packs => packs.slice(0, 8));
export const expandedMockAcademicTasks: WritingAcademicPack[] = [lines, bars, pies, tables, maps, processes, mixed].flatMap(packs => packs.slice(8));
